struct Particle{float x,y,z,vx,vy,vz,mass;};
struct Src{float x,y,z,m;};
extern "C" __global__ void nbody_step_naive(const Particle* in,Particle* out,int n,float dt){
 int t=threadIdx.x,i=blockIdx.x*blockDim.x+t; bool ok=i<n; Particle p;
 if(ok)p=in[i];
 float fx=0,fy=0,fz=0; __shared__ Src tile[256];
 for(int b=0;b<n;b+=blockDim.x){
  int j=b+t;
  if(j<n)tile[t]={in[j].x,in[j].y,in[j].z,in[j].mass};
  else tile[t]={0,0,0,0};
  __syncthreads();
  if(ok)for(int k=0;k<blockDim.x&&b+k<n;++k){
   j=b+k;if(j==i)continue; Src s=tile[k];
   float dx=s.x-p.x,dy=s.y-p.y,dz=s.z-p.z;
   if(dx!=0||dy!=0||dz!=0){
    float r=rsqrtf(dx*dx+dy*dy+dz*dz+0.001f);
    float f=((s.m*r)*r)*r;
    fx+=f*dx;fy+=f*dy;fz+=f*dz;
   }
  }
  __syncthreads();
 }
 if(ok){p.vx+=fx*dt;p.vy+=fy*dt;p.vz+=fz*dt;
  p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;out[i]=p;}
}

